#include <iostream>
#include <string>
#include <algorithm>
#include <cctype>

int main() {
    int totalChars;
    std::cin >> totalChars;
    std::cin.ignore(); // To consume the newline after the integer input
    std::string inputLine;
    std::getline(std::cin, inputLine);

    int countWordsInBraces = 0;
    int maxWordSize = 0;
    bool inBracesFlag = false;
    std::string currentWord;

    auto handleWord = [&](const std::string& word, bool inBraces) {
        int len = word.length();
        if (len > 0) {
            if (inBraces) {
                ++countWordsInBraces;
            } else {
                maxWordSize = std::max(maxWordSize, len);
            }
        }
    };

    for (int index = 0; index < totalChars; ++index) {
        char ch = inputLine[index];

        if (ch == '_') {
            handleWord(currentWord, inBracesFlag);
            currentWord.clear();
        } else if (ch == '(') {
            handleWord(currentWord, inBracesFlag);
            currentWord.clear();
            inBracesFlag = true;
        } else if (ch == ')') {
            handleWord(currentWord, inBracesFlag);
            currentWord.clear();
            inBracesFlag = false;
        } else if (std::isalpha(static_cast<unsigned char>(ch))) {
            currentWord += ch;
        }
    }

    handleWord(currentWord, inBracesFlag);

    std::cout << maxWordSize << " " << countWordsInBraces << std::endl;

    return 0;
}
